"""Design audit over existing public research; never writes the research owners."""
from pathlib import Path
import json,hashlib
R=Path(__file__).resolve().parents[5];D=Path(__file__).resolve().parent.parent
p=R/'enterprise-knowledge/banking/research-model/Assessment-Overlay.json';a=json.loads(p.read_text());sources={s['id']:s for s in a['sources']};claims={c['id']:c for c in a['claims']}
ids=['LBG-Q326-DEPOSITS','LBG-Q326-PROFIT','LBG-Q326-INVESTMENT','LBG-A2030-SAVINGS','LBG-A2030-CIR','LBG-A2030-INVESTMENT','LBG-ENVOY-GOOGLE','LBG-ENVOY-CONTROLS','LBG-BRAND26-TIMING','LBG-BRAND26-NO-ROLES','LBG-AR25-DEPOSITS','LBG-VERTEX','LBG-MODELS','LBG-HEDGE','LBG-TECH-COST','LBG-CUSTOMERS']
record={'authority':'Design-only audit/index; existing research and canonical authority unchanged','audit_date':'2026-11-14','source_commit':'208015805e12772fb425cb014870db697f878f6d','owner':'Existing Assessment-Overlay / Understanding-Review / Enterprise Twin; no new model or relationship owner','research_path':str(p.relative_to(R)),'research_sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'claims':{}}
for cid in ids:
 c=claims[cid];sids=c['source_ids'];record['claims'][cid]={k:v for k,v in c.items() if k not in ['primary_quotes','repository_quote']}
 record['claims'][cid]['source_records']=[{k:v for k,v in sources[sid].items() if k in ['id','title','url','publication_date','reporting_period','retrieved_at','verification','limitation','text_path','reviewed_by']} for sid in sids]
record['display_decisions']={'current_financials':'Only reviewed 30 Sep 2026 customer deposits and nine-month statutory pretax profit shown as current actuals. 2030 cost:income is visibly a target. No reconstructed current income, operating cost or revenue growth.','businesses':'Customer/business roles and historic business-area labels are distinguished from current segment/legal-entity facts; no org-chart assertion.','brands':'Lloyds/Halifax transition is supported by July 2026 announcement; delivery through 2027 not assumed complete. Bank of Scotland and Scottish Widows retained only as historic portfolio-brand references with current legal ownership unverified.','technology':'Envoy/Google collaboration source supported; Vertex and model migration are older repository-reported context, not a verified current inventory.','customers':'Household and business customer roles; no named corporate customer relationship.','regulators':'BoE, PRA and FCA retain distinct roles. PRA shown as BoE prudential function, not a separate bank/company. Sector policy does not prove applicability to a Lloyds legal entity.','suppliers':'Single named supported platform collaboration; no inferred exclusive contract, external scope or workshare.','visuals':'AI-generated original conceptual architectural scenes; not evidence, real offices, actual campus topology, tenant or relative financial scale.'}
gaps=[
('FIN-01','Current consolidated income and operating costs','Latest official interim/annual income statement and reconciliation; net interest income, other income, total income, operating expenses, impairment, statutory vs underlying profit, GBP units and reporting periods.','Blocks quantified money-flow decomposition; old FY2024 fixture is not current evidence.'),
('FIN-02','Comparable growth and profitability','Company-disclosed matched-period income/cost/earnings growth, restatements, organic/FX boundary, margins and segment consistency.','No percentage growth or invented denominator shown.'),
('ORG-01','Current segments, brands and legal subsidiaries','Current official segment note, group organisation/subsidiary schedule, ownership percentages and entity IDs; distinguish brands, divisions, subsidiaries and regulated legal entities.','Historical three-division/four-brand profile does not prove current hierarchy.'),
('OPS-01','Operations and important technology systems','Official current operating-model disclosures, critical services, named systems/platform purpose, rollout status and dated dependencies.','Envoy/Vertex does not establish full core/payments estate or architecture.'),
('REL-01','Suppliers, partners and customers','Official specific relationship announcements/filings, parties/legal IDs, service, geography, date, status, rights and counter-evidence; current workshare/contract/renewal only if disclosed.','No supplier logos, unnamed customers or contracts invented.'),
('REG-01','Legal-entity regulatory applicability','Current official PRA/FCA register and entity/activity-level scope, BoE/PRA institutional structure source, permissions/firm numbers and dates.','Sector-policy actor links remain context, no firm-specific obligation graph.'),
('ORG-02','Current leadership and accountability','Official current governance/leadership page and report dates; role/entity scope and decision authority; no inferred buyer.','No named executive or buyer is drawn.'),
('INF-01','Infrastructure operating relationships','Official current CHAPS/RTGS and other payment-system operator/remit/participation sources and dates.','Infrastructure is depicted as sector function, not a particular bank contract.'),
('COM-01','Remaining influence and external need','Human-reviewed validation of unresolved outcomes, decision dates, current incumbent coverage, authorised access and external scope.','No early opportunity classification, budget, procurement or Pipeline write.')]
record['targeted_research_gaps']=[{'id':i,'need':n,'requested_evidence':r,'impact':impact,'action':'Targeted enrichment request recorded only; not commissioned, fetched or promoted by this design sprint'} for i,n,r,impact in gaps]
(D/'Research-Audit.json').write_text(json.dumps(record,indent=2)+'\n')
(D/'Research-Gaps.md').write_text('# LJ-1R targeted enrichment requests\n\nExisting-source audit only. These are unresolved inputs, not new research facts or automatically commissioned work. No canonical/historical data has been altered.\n\n'+''.join(f'## {i} · {n}\n\nRequest: {r}\n\nDesign boundary: {impact}\n\n' for i,n,r,impact in gaps))
print('Audited',len(ids),'existing claims;',len(gaps),'targeted gaps recorded')
